SET DEFINE ON
SET ECHO OFF
SET FEEDBACK ON
SET SERVEROUTPUT ON SIZE UNLIMITED
SET SQLBLANKLINES ON
WHENEVER SQLERROR EXIT SQL.SQLCODE

DEFINE lluser_password = "&1"
DEFINE connect_identifier = "&2"

PROMPT =====================================================
PROMPT Media LiveStack SQLcl platform handoff loader
PROMPT Run as: sql ADMIN/<admin-password>@<service> @media-platform-handoff-loader.sql <lluser-password> <service>
PROMPT =====================================================

DECLARE
  v_current_user VARCHAR2(128) := SYS_CONTEXT('USERENV', 'SESSION_USER');
BEGIN
  IF v_current_user = 'ADMIN' THEN
    DBMS_OUTPUT.PUT_LINE('ADMIN prep started for LLUSER.');
  ELSE
    RAISE_APPLICATION_ERROR(-20000, 'Start this loader as ADMIN so platform prep and grants run before LLUSER DDL. Current user: ' || v_current_user);
  END IF;
END;
/

DECLARE
  v_stmt VARCHAR2(4000);
BEGIN
  v_stmt := 'ALTER USER LLUSER IDENTIFIED' || ' BY "' || REPLACE('&lluser_password', '"', '""') || '" ACCOUNT UNLOCK';
  EXECUTE IMMEDIATE v_stmt;
END;
/
GRANT CREATE SESSION TO LLUSER;
GRANT CREATE TABLE TO LLUSER;
GRANT CREATE VIEW TO LLUSER;
GRANT CREATE SEQUENCE TO LLUSER;
GRANT CREATE PROCEDURE TO LLUSER;
GRANT CREATE TRIGGER TO LLUSER;
GRANT CREATE TYPE TO LLUSER;
GRANT CREATE JOB TO LLUSER;
GRANT CREATE MINING MODEL TO LLUSER;
GRANT UNLIMITED TABLESPACE TO LLUSER;
GRANT SODA_APP TO LLUSER;
GRANT GRAPH_DEVELOPER TO LLUSER;
GRANT EXECUTE ON MDSYS.SDO_GEOM TO LLUSER;
GRANT EXECUTE ON MDSYS.SDO_UTIL TO LLUSER;
GRANT EXECUTE ON MDSYS.SDO_CS TO LLUSER;
GRANT EXECUTE ON SYS.DBMS_RLS TO LLUSER;
GRANT EXECUTE ON SYS.DBMS_DATA_MINING TO LLUSER;
GRANT EXECUTE ON SYS.DBMS_VECTOR TO LLUSER;
GRANT SELECT ON MINING MODEL ALL_MINILM_L12_V2 TO LLUSER;

CONNECT LLUSER/"&lluser_password"@"&connect_identifier"
SET DEFINE OFF
SET SERVEROUTPUT ON SIZE UNLIMITED
WHENEVER SQLERROR EXIT SQL.SQLCODE

DECLARE
  v_expected_user VARCHAR2(30) := 'LLUSER';
BEGIN
  IF USER <> v_expected_user THEN
    RAISE_APPLICATION_ERROR(-20001, 'DDL/data section must run as LLUSER. Current user: ' || USER);
  END IF;
END;
/

PROMPT Dropping prior Media workshop objects
BEGIN
  FOR rec IN (SELECT model_name FROM user_mining_models WHERE model_name IN ('DEMAND_SURGE_MODEL','CUSTOMER_SEGMENT_MODEL','REVENUE_PREDICT_MODEL','PRODUCT_CLUSTER_MODEL')) LOOP
    DBMS_DATA_MINING.DROP_MODEL(rec.model_name);
  END LOOP;
EXCEPTION WHEN OTHERS THEN NULL;
END;
/
BEGIN EXECUTE IMMEDIATE 'DROP PROPERTY GRAPH influencer_network'; EXCEPTION WHEN OTHERS THEN NULL; END;
/
BEGIN
  FOR rec IN (
    SELECT object_type, object_name
    FROM user_objects
    WHERE object_name IN (
      'MEDIA_CONTENT_ASSETS_V','MEDIA_CAMPAIGN_ORDERS_V','MEDIA_AUDIENCE_SIGNALS_V','MEDIA_DISTRIBUTION_CAPACITY_V','MEDIA_CREATOR_RELATIONSHIPS_V',
      'ORDERS_DV','PRODUCTS_INVENTORY_DV','REFRESH_MEDIA_VECTOR_ARTIFACTS','REBUILD_MEDIA_OML_MODELS','FIND_MATCHING_PRODUCTS','BATCH_SEMANTIC_MATCH',
      'SEARCH_PRODUCTS_BY_VECTOR','SEARCH_PRODUCTS_BY_TEXT','DETECT_TRENDING_PRODUCTS','CHECK_PRODUCT_INVENTORY','FIND_BEST_FULFILLMENT','GET_INFLUENCER_NETWORK','LOG_AGENT_DECISION',
      'FIND_NEAREST_CENTERS','OPTIMAL_FULFILLMENT'
    )
    ORDER BY CASE object_type WHEN 'VIEW' THEN 1 WHEN 'FUNCTION' THEN 2 WHEN 'PROCEDURE' THEN 3 ELSE 4 END
  ) LOOP
    BEGIN
      EXECUTE IMMEDIATE 'DROP ' || rec.object_type || ' ' || rec.object_name;
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END;
/
BEGIN
  FOR rec IN (
    SELECT table_name FROM user_tables
    WHERE table_name IN (
      'OML_DEMAND_SETTINGS','OML_CUSTOMER_SEGMENT_SETTINGS','OML_REVENUE_SETTINGS','OML_PRODUCT_CLUSTER_SETTINGS',
      'SEMANTIC_MATCHES','POST_EMBEDDINGS','PRODUCT_EMBEDDINGS','FULFILLMENT_ZONES','DEMAND_REGIONS','BRAND_INFLUENCER_LINKS','INFLUENCER_CONNECTIONS',
      'EVENT_STREAM','PRODUCT_ATTRIBUTES','APP_DATASET_STATE','APP_USERS','AGENT_ACTIONS','SHIPMENTS','DEMAND_FORECASTS','POST_PRODUCT_MENTIONS','SOCIAL_POSTS','INFLUENCERS',
      'ORDER_ITEMS','ORDERS','CUSTOMERS','INVENTORY','FULFILLMENT_CENTERS','PRODUCTS','BRANDS'
    )
  ) LOOP
    BEGIN
      EXECUTE IMMEDIATE 'DROP TABLE ' || rec.table_name || ' CASCADE CONSTRAINTS PURGE';
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
  END LOOP;
END;
/
DELETE FROM user_sdo_geom_metadata WHERE table_name IN ('FULFILLMENT_CENTERS','CUSTOMERS','FULFILLMENT_ZONES','DEMAND_REGIONS');
COMMIT;

PROMPT Creating core schema objects

CREATE TABLE brands (
    brand_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    brand_name        VARCHAR2(200)  NOT NULL,
    brand_slug        VARCHAR2(100)  NOT NULL UNIQUE,
    brand_category    VARCHAR2(100),
    headquarters_city VARCHAR2(100),
    headquarters_lat  NUMBER(10,7),
    headquarters_lon  NUMBER(11,7),
    founded_year      NUMBER(4),
    annual_revenue    NUMBER(15,2),
    social_tier       VARCHAR2(20) DEFAULT 'standard'
                      CHECK (social_tier IN ('emerging','standard','premium','luxury')),
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    updated_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE products (
    product_id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    brand_id          NUMBER NOT NULL REFERENCES brands(brand_id),
    sku               VARCHAR2(50)  NOT NULL UNIQUE,
    product_name      VARCHAR2(300) NOT NULL,
    description       CLOB,
    category          VARCHAR2(100),
    subcategory       VARCHAR2(100),
    unit_price        NUMBER(10,2)  NOT NULL,
    unit_cost         NUMBER(10,2),
    weight_kg         NUMBER(8,3),
    is_active         NUMBER(1) DEFAULT 1,
    launch_date       DATE,
    tags              VARCHAR2(1000),  
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    updated_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
) INMEMORY MEMCOMPRESS FOR QUERY HIGH;

CREATE INDEX idx_products_brand    ON products(brand_id);
CREATE INDEX idx_products_category ON products(category, subcategory);
CREATE INDEX idx_products_active   ON products(is_active);

CREATE TABLE fulfillment_centers (
    center_id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    center_name       VARCHAR2(200)  NOT NULL,
    center_type       VARCHAR2(30)   DEFAULT 'warehouse'
                      CHECK (center_type IN ('warehouse','distribution','micro','drop_ship','store')),
    address_line1     VARCHAR2(300),
    city              VARCHAR2(100),
    state_province    VARCHAR2(100),
    postal_code       VARCHAR2(20),
    country           VARCHAR2(3) DEFAULT 'US',
    latitude          NUMBER(10,7) NOT NULL,
    longitude         NUMBER(11,7) NOT NULL,
    capacity_units    NUMBER(10) DEFAULT 100000,
    current_load_pct  NUMBER(5,2) DEFAULT 0,
    is_active         NUMBER(1) DEFAULT 1,
    operating_hours   VARCHAR2(50) DEFAULT '06:00-22:00',
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE inventory (
    inventory_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    center_id         NUMBER NOT NULL REFERENCES fulfillment_centers(center_id),
    quantity_on_hand  NUMBER(10) DEFAULT 0,
    quantity_reserved NUMBER(10) DEFAULT 0,
    quantity_incoming NUMBER(10) DEFAULT 0,
    reorder_point     NUMBER(10) DEFAULT 50,
    reorder_qty       NUMBER(10) DEFAULT 200,
    last_restock_date DATE,
    updated_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_inventory UNIQUE (product_id, center_id)
);

CREATE INDEX idx_inventory_product ON inventory(product_id);
CREATE INDEX idx_inventory_center  ON inventory(center_id);

CREATE TABLE customers (
    customer_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    email             VARCHAR2(300)  NOT NULL UNIQUE,
    first_name        VARCHAR2(100),
    last_name         VARCHAR2(100),
    city              VARCHAR2(100),
    state_province    VARCHAR2(100),
    postal_code       VARCHAR2(20),
    country           VARCHAR2(3) DEFAULT 'US',
    latitude          NUMBER(10,7),
    longitude         NUMBER(11,7),
    location          SDO_GEOMETRY,
    customer_tier     VARCHAR2(20) DEFAULT 'standard'
                      CHECK (customer_tier IN ('new','standard','preferred','vip')),
    lifetime_value    NUMBER(12,2) DEFAULT 0,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE orders (
    order_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    customer_id       NUMBER NOT NULL REFERENCES customers(customer_id),
    order_status      VARCHAR2(30) DEFAULT 'pending'
                      CHECK (order_status IN ('pending','confirmed','processing',
                             'shipped','delivered','cancelled','returned')),
    order_total       NUMBER(12,2),
    shipping_cost     NUMBER(8,2) DEFAULT 0,
    fulfillment_center_id NUMBER REFERENCES fulfillment_centers(center_id),
    shipping_lat      NUMBER(10,7),
    shipping_lon      NUMBER(11,7),
    estimated_delivery DATE,
    actual_delivery    DATE,
    social_source_id   NUMBER,         
    demand_score       NUMBER(5,2),    
    created_at         TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    updated_at         TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
) INMEMORY MEMCOMPRESS FOR QUERY HIGH;

CREATE INDEX idx_orders_customer ON orders(customer_id);
CREATE INDEX idx_orders_status   ON orders(order_status);
CREATE INDEX idx_orders_center   ON orders(fulfillment_center_id);
CREATE INDEX idx_orders_created  ON orders(created_at);

CREATE TABLE order_items (
    item_id           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    order_id          NUMBER NOT NULL REFERENCES orders(order_id),
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    quantity          NUMBER(6)  NOT NULL,
    unit_price        NUMBER(10,2) NOT NULL,
    line_total        NUMBER(12,2) GENERATED ALWAYS AS (quantity * unit_price) VIRTUAL,
    fulfilled_from    NUMBER REFERENCES fulfillment_centers(center_id)
) INMEMORY MEMCOMPRESS FOR QUERY HIGH;

CREATE INDEX idx_oitems_order   ON order_items(order_id);
CREATE INDEX idx_oitems_product ON order_items(product_id);

CREATE TABLE influencers (
    influencer_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    handle            VARCHAR2(200) NOT NULL UNIQUE,
    display_name      VARCHAR2(200),
    platform          VARCHAR2(50) DEFAULT 'instagram'
                      CHECK (platform IN ('instagram','tiktok','twitter','youtube','threads')),
    follower_count    NUMBER(12) DEFAULT 0,
    engagement_rate   NUMBER(5,4) DEFAULT 0,   
    influence_score   NUMBER(5,2) DEFAULT 0,   
    niche             VARCHAR2(100),
    city              VARCHAR2(100),
    region            VARCHAR2(100),            
    country           VARCHAR2(3) DEFAULT 'US',
    is_verified       NUMBER(1) DEFAULT 0,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE INDEX idx_influencers_platform ON influencers(platform);
CREATE INDEX idx_influencers_score    ON influencers(influence_score DESC);

CREATE TABLE social_posts (
    post_id           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    influencer_id     NUMBER REFERENCES influencers(influencer_id),
    platform          VARCHAR2(50),
    external_post_id  VARCHAR2(200),
    post_text         CLOB,
    posted_at         TIMESTAMP NOT NULL,
    likes_count       NUMBER(10) DEFAULT 0,
    shares_count      NUMBER(10) DEFAULT 0,
    comments_count    NUMBER(10) DEFAULT 0,
    views_count       NUMBER(12) DEFAULT 0,
    sentiment_score   NUMBER(4,3),       
    virality_score    NUMBER(5,2),       
    detected_products VARCHAR2(2000),    
    momentum_flag     VARCHAR2(20) DEFAULT 'normal'
                      CHECK (momentum_flag IN ('normal','rising','viral','mega_viral')),
    processed_at      TIMESTAMP,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
) INMEMORY MEMCOMPRESS FOR QUERY HIGH;

CREATE INDEX idx_social_influencer ON social_posts(influencer_id);
CREATE INDEX idx_social_posted     ON social_posts(posted_at DESC);
CREATE INDEX idx_social_momentum   ON social_posts(momentum_flag);
CREATE INDEX idx_social_virality   ON social_posts(virality_score DESC);

CREATE TABLE post_product_mentions (
    mention_id        NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    post_id           NUMBER NOT NULL REFERENCES social_posts(post_id),
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    confidence_score  NUMBER(4,3) DEFAULT 1.0,  
    mention_type      VARCHAR2(30) DEFAULT 'direct'
                      CHECK (mention_type IN ('direct','semantic','hashtag','visual','inferred')),
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_post_product UNIQUE (post_id, product_id)
);

CREATE INDEX idx_mentions_product ON post_product_mentions(product_id);
CREATE INDEX idx_mentions_post    ON post_product_mentions(post_id);

CREATE TABLE demand_forecasts (
    forecast_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    region            VARCHAR2(100),
    forecast_date     DATE NOT NULL,
    predicted_demand  NUMBER(10) NOT NULL,
    confidence_low    NUMBER(10),
    confidence_high   NUMBER(10),
    social_factor     NUMBER(5,2) DEFAULT 1.0,  
    model_version     VARCHAR2(50),
    explanation       CLOB,    
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE INDEX idx_forecast_product ON demand_forecasts(product_id, forecast_date);

CREATE TABLE shipments (
    shipment_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    order_id          NUMBER NOT NULL REFERENCES orders(order_id),
    center_id         NUMBER NOT NULL REFERENCES fulfillment_centers(center_id),
    carrier           VARCHAR2(100),
    tracking_number   VARCHAR2(200),
    ship_status       VARCHAR2(30) DEFAULT 'preparing'
                      CHECK (ship_status IN ('preparing','picked','packed','shipped',
                             'in_transit','out_for_delivery','delivered','exception')),
    distance_km       NUMBER(8,2),
    estimated_hours   NUMBER(6,2),
    ship_cost         NUMBER(8,2),
    shipped_at        TIMESTAMP,
    delivered_at      TIMESTAMP,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE INDEX idx_shipments_order  ON shipments(order_id);
CREATE INDEX idx_shipments_center ON shipments(center_id);

CREATE TABLE agent_actions (
    action_id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    agent_name        VARCHAR2(100) NOT NULL,
    action_type       VARCHAR2(100) NOT NULL,
    entity_type       VARCHAR2(50),      
    entity_id         NUMBER,
    decision_payload  CLOB,              
    confidence        NUMBER(4,3),
    execution_status  VARCHAR2(30) DEFAULT 'proposed'
                      CHECK (execution_status IN ('proposed','approved','executing',
                             'completed','failed','rolled_back')),
    executed_at       TIMESTAMP,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE INDEX idx_agent_actions_type   ON agent_actions(action_type);
CREATE INDEX idx_agent_actions_entity ON agent_actions(entity_type, entity_id);

CREATE TABLE app_users (
    user_id           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    username          VARCHAR2(100) NOT NULL UNIQUE,
    password_hash     VARCHAR2(500) NOT NULL,
    full_name         VARCHAR2(200),
    email             VARCHAR2(300),
    role              VARCHAR2(30) NOT NULL
                      CHECK (role IN ('admin','analyst','fulfillment_mgr',
                             'merchandiser','viewer')),
    region            VARCHAR2(100),
    is_active         NUMBER(1) DEFAULT 1,
    last_login        TIMESTAMP,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE app_dataset_state (
    state_id          NUMBER(1) PRIMARY KEY
                      CHECK (state_id = 1),
    active_source     VARCHAR2(20) NOT NULL
                      CHECK (active_source IN ('demo','custom')),
    active_label      VARCHAR2(100) NOT NULL,
    active_version    VARCHAR2(20),
    updated_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00' NOT NULL
);

COMMIT;

CREATE TABLE product_attributes (
    attr_id       NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    product_id    NUMBER NOT NULL REFERENCES products(product_id),
    attributes    JSON NOT NULL,
    created_at    TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_prod_attr UNIQUE (product_id)
);

CREATE SEARCH INDEX idx_prodattr_json ON product_attributes(attributes)
    FOR JSON;

CREATE TABLE event_stream (
    event_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    event_type    VARCHAR2(100) NOT NULL,
    event_source  VARCHAR2(100),
    event_data    JSON NOT NULL,
    correlation_id VARCHAR2(100),
    processed     NUMBER(1) DEFAULT 0,
    created_at    TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE INDEX idx_events_type      ON event_stream(event_type);
CREATE INDEX idx_events_processed ON event_stream(processed, created_at);
CREATE INDEX idx_events_corr      ON event_stream(correlation_id);

CREATE OR REPLACE JSON RELATIONAL DUALITY VIEW orders_dv AS
SELECT JSON {
    '_id'         : o.order_id,       
    'customerId'  : o.customer_id,
    'status'      : o.order_status,
    'total'       : o.order_total,
    'shippingCost': o.shipping_cost,
    'demandScore' : o.demand_score,
    'createdAt'   : o.created_at,
    'items' : [
        SELECT JSON {
            'itemId'    : oi.item_id,
            'productId' : oi.product_id,
            'quantity'  : oi.quantity,
            'unitPrice' : oi.unit_price
        }
        FROM order_items oi WITH UPDATE
        WHERE oi.order_id = o.order_id
    ]
}
FROM orders o WITH UPDATE;

CREATE OR REPLACE JSON RELATIONAL DUALITY VIEW products_inventory_dv AS
SELECT JSON {
    '_id'          : p.product_id,    
    'sku'          : p.sku,
    'productName'  : p.product_name,
    'category'     : p.category,
    'unitPrice'    : p.unit_price,
    'brand'        : (SELECT b.brand_name FROM brands b WHERE b.brand_id = p.brand_id),
    'inventory'    : [
        SELECT JSON {
            'centerId'        : i.center_id,
            'quantityOnHand'  : i.quantity_on_hand,
            'quantityReserved': i.quantity_reserved
        }
        FROM inventory i WITH UPDATE
        WHERE i.product_id = p.product_id
    ]
}
FROM products p WITH UPDATE;

COMMIT;


PROMPT Creating spatial extension tables
ALTER TABLE fulfillment_centers ADD (location SDO_GEOMETRY);

