    max_delivery_hrs  NUMBER(5,1),
    zone_boundary     SDO_GEOMETRY,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE demand_regions (
    region_id         NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    region_name       VARCHAR2(100) NOT NULL,
    region_type       VARCHAR2(30) DEFAULT 'metro' CHECK (region_type IN ('metro','state','region','zip_cluster')),
    boundary          SDO_GEOMETRY,
    population        NUMBER(10),
    avg_income        NUMBER(10,2),
    social_density    NUMBER(8,2),
    demand_index      NUMBER(5,2) DEFAULT 50,
    updated_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);

CREATE TABLE influencer_connections (
    connection_id     NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    from_influencer   NUMBER NOT NULL REFERENCES influencers(influencer_id),
    to_influencer     NUMBER NOT NULL REFERENCES influencers(influencer_id),
    connection_type   VARCHAR2(30) NOT NULL
                      CHECK (connection_type IN ('follows','collaborates','mentioned',
                             'reshared','tagged','duet','inspired_by')),
    strength          NUMBER(4,3) DEFAULT 0.5,  
    interaction_count NUMBER(8) DEFAULT 1,
    first_seen        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    last_interaction  TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_connection UNIQUE (from_influencer, to_influencer, connection_type)
);

CREATE INDEX idx_conn_from ON influencer_connections(from_influencer);
CREATE INDEX idx_conn_to   ON influencer_connections(to_influencer);

CREATE TABLE brand_influencer_links (
    link_id           NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    brand_id          NUMBER NOT NULL REFERENCES brands(brand_id),
    influencer_id     NUMBER NOT NULL REFERENCES influencers(influencer_id),
    relationship_type VARCHAR2(30) DEFAULT 'organic'
                      CHECK (relationship_type IN ('organic','sponsored','ambassador',
                             'affiliate','competitor_mention')),
    post_count        NUMBER(8) DEFAULT 0,
    avg_engagement    NUMBER(8,4) DEFAULT 0,
    revenue_attributed NUMBER(12,2) DEFAULT 0,
    first_mention     TIMESTAMP,
    last_mention      TIMESTAMP,
    CONSTRAINT uq_media_brand_inf UNIQUE (brand_id, influencer_id)
);


PROMPT Creating vector objects
CREATE TABLE product_embeddings (
    embedding_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    embedding_model   VARCHAR2(100) DEFAULT 'all_MiniLM_L12_v2',
    embedding_text    CLOB,
    embedding         VECTOR(384),
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_prod_embed UNIQUE (product_id, embedding_model)
);

CREATE TABLE post_embeddings (
    embedding_id      NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    post_id           NUMBER NOT NULL REFERENCES social_posts(post_id),
    embedding_model   VARCHAR2(100) DEFAULT 'all_MiniLM_L12_v2',
    embedding_text    CLOB,
    embedding         VECTOR(384),
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00',
    CONSTRAINT uq_media_post_embed UNIQUE (post_id, embedding_model)
);

CREATE TABLE semantic_matches (
    match_id          NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY,
    post_id           NUMBER NOT NULL REFERENCES social_posts(post_id),
    product_id        NUMBER NOT NULL REFERENCES products(product_id),
    similarity_score  NUMBER(6,5),
    match_rank        NUMBER(4),
    match_method      VARCHAR2(30) DEFAULT 'vector' CHECK (match_method IN ('vector','keyword','hybrid','visual')),
    verified          NUMBER(1) DEFAULT 0,
    created_at        TIMESTAMP DEFAULT TIMESTAMP '2026-05-05 16:30:00'
);
CREATE INDEX idx_semantic_post    ON semantic_matches(post_id);
CREATE INDEX idx_semantic_product ON semantic_matches(product_id);
CREATE INDEX idx_semantic_score   ON semantic_matches(similarity_score DESC);

CREATE OR REPLACE FUNCTION search_products_by_text (
    p_query_text IN CLOB,
    p_top_k      IN NUMBER DEFAULT 10
) RETURN SYS_REFCURSOR
AS
    v_results SYS_REFCURSOR;
    v_query_vec VECTOR(384);
BEGIN
    SELECT VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING p_query_text AS DATA)
    INTO   v_query_vec
    FROM   dual;

    OPEN v_results FOR
        SELECT p.product_id,
               p.product_name,
               p.category,
               p.unit_price,
               b.brand_name,
               ROUND(1 - VECTOR_DISTANCE(pe.embedding, v_query_vec, COSINE), 5) AS similarity_score
        FROM product_embeddings pe
        JOIN products p ON pe.product_id = p.product_id
        JOIN brands   b ON p.brand_id    = b.brand_id
        ORDER BY VECTOR_DISTANCE(pe.embedding, v_query_vec, COSINE)
        FETCH APPROXIMATE FIRST p_top_k ROWS ONLY;
    RETURN v_results;
END;
/

