PROMPT Rebuilding vector artifacts from fixed source text
CREATE OR REPLACE PROCEDURE refresh_media_vector_artifacts
AS
BEGIN
    DELETE FROM semantic_matches;
    DELETE FROM post_embeddings;
    DELETE FROM product_embeddings;
    SELECT p.product_id,
           TO_CLOB(p.product_name || ' ' || NVL(p.category, '') || ' ' || NVL(DBMS_LOB.SUBSTR(p.description, 1000, 1), '') || ' ' || b.brand_name),
           VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING p.product_name || ' ' || NVL(p.category, '') || ' ' || NVL(DBMS_LOB.SUBSTR(p.description, 1000, 1), '') || ' ' || b.brand_name AS DATA),
           TIMESTAMP '2026-05-05 16:30:00'
    FROM products p JOIN brands b ON b.brand_id = p.brand_id WHERE p.is_active = 1;
    SELECT sp.post_id, TO_CLOB(DBMS_LOB.SUBSTR(sp.post_text, 500, 1)),
           VECTOR_EMBEDDING(ADMIN.ALL_MINILM_L12_V2 USING DBMS_LOB.SUBSTR(sp.post_text, 500, 1) AS DATA),
           TIMESTAMP '2026-05-05 16:30:00'
    FROM social_posts sp;
    SELECT post_id, product_id, similarity_score, match_rank, 'vector', TIMESTAMP '2026-05-05 16:30:00'
    FROM (
        SELECT pe.post_id, pre.product_id,
               ROUND(1 - VECTOR_DISTANCE(pe.embedding, pre.embedding, COSINE), 5) AS similarity_score,
               ROW_NUMBER() OVER (PARTITION BY pe.post_id ORDER BY VECTOR_DISTANCE(pe.embedding, pre.embedding, COSINE)) AS match_rank
        FROM post_embeddings pe
        JOIN social_posts sp ON sp.post_id = pe.post_id
        CROSS JOIN product_embeddings pre
        WHERE sp.momentum_flag IN ('viral', 'mega_viral')
    )
    WHERE match_rank <= 3;
    COMMIT;
END;
/
BEGIN refresh_media_vector_artifacts; END;
/
CREATE VECTOR INDEX idx_media_product_vec ON product_embeddings(embedding) ORGANIZATION NEIGHBOR PARTITIONS WITH DISTANCE COSINE WITH TARGET ACCURACY 95;
CREATE VECTOR INDEX idx_media_post_vec ON post_embeddings(embedding) ORGANIZATION NEIGHBOR PARTITIONS WITH DISTANCE COSINE WITH TARGET ACCURACY 95;

PROMPT Creating graph object after deterministic edge load
CREATE PROPERTY GRAPH influencer_network
    VERTEX TABLES (
        influencers KEY (influencer_id) LABEL influencer PROPERTIES (influencer_id, handle, display_name, platform, follower_count, engagement_rate, influence_score, niche, city, region, is_verified),
        brands KEY (brand_id) LABEL brand PROPERTIES (brand_id, brand_name, brand_category, social_tier),
        products KEY (product_id) LABEL product PROPERTIES (product_id, product_name, category, unit_price),
        social_posts KEY (post_id) LABEL social_post PROPERTIES (post_id, platform, posted_at, virality_score, momentum_flag)
    )
    EDGE TABLES (
        influencer_connections KEY (connection_id) SOURCE KEY (from_influencer) REFERENCES influencers (influencer_id) DESTINATION KEY (to_influencer) REFERENCES influencers (influencer_id) LABEL connects_to PROPERTIES (connection_type, strength, interaction_count),
        brand_influencer_links KEY (link_id) SOURCE KEY (influencer_id) REFERENCES influencers (influencer_id) DESTINATION KEY (brand_id) REFERENCES brands (brand_id) LABEL promotes PROPERTIES (relationship_type, post_count, avg_engagement, revenue_attributed),
        post_product_mentions KEY (mention_id) SOURCE KEY (post_id) REFERENCES social_posts (post_id) DESTINATION KEY (product_id) REFERENCES products (product_id) LABEL mentions_product PROPERTIES (confidence_score, mention_type)
    );

CREATE OR REPLACE VIEW media_content_assets_v AS
SELECT
  p.product_id,
  p.sku AS content_asset_code,
  p.product_name AS content_asset,
  p.description AS content_description,
  p.category AS content_category,
  p.subcategory AS content_subcategory,
  b.brand_id AS studio_label_id,
  b.brand_name AS studio_or_label,
  p.unit_price AS campaign_value_proxy,
  p.unit_cost AS distribution_cost_proxy,
  p.is_active,
  p.launch_date,
  NVL(cap.total_capacity_units, 0) AS total_capacity_units,
  NVL(cap.reserved_capacity_units, 0) AS reserved_capacity_units,
  NVL(sig.signal_count, 0) AS audience_signal_count,
  sig.avg_virality_score,
  sig.latest_signal_at
FROM products p
JOIN brands b ON b.brand_id = p.brand_id
LEFT JOIN (
  SELECT
    product_id,
    SUM(quantity_on_hand) AS total_capacity_units,
    SUM(quantity_reserved) AS reserved_capacity_units
  FROM inventory
  GROUP BY product_id
) cap ON cap.product_id = p.product_id
LEFT JOIN (
  SELECT
    ppm.product_id,
    COUNT(DISTINCT sp.post_id) AS signal_count,
    ROUND(AVG(sp.virality_score), 2) AS avg_virality_score,
    MAX(sp.posted_at) AS latest_signal_at
  FROM post_product_mentions ppm
  JOIN social_posts sp ON sp.post_id = ppm.post_id
  GROUP BY ppm.product_id
) sig ON sig.product_id = p.product_id;

CREATE OR REPLACE VIEW media_campaign_orders_v AS
SELECT
  o.order_id AS campaign_order_id,
  o.order_status AS campaign_status,
  o.order_total AS campaign_value,
  o.shipping_cost AS distribution_cost,
  o.created_at AS campaign_created_at,
  o.social_source_id AS audience_signal_source_id,
  c.customer_id AS audience_account_id,
  TRIM(c.first_name || ' ' || c.last_name) AS audience_account,
  c.customer_tier AS audience_tier,
  c.city AS audience_city,
  c.state_province AS audience_region,
  fc.center_id AS distribution_hub_id,
  fc.center_name AS distribution_hub,
  COUNT(oi.item_id) AS line_count,
  SUM(oi.quantity) AS requested_units
FROM orders o
JOIN customers c ON c.customer_id = o.customer_id
LEFT JOIN fulfillment_centers fc ON fc.center_id = o.fulfillment_center_id
LEFT JOIN order_items oi ON oi.order_id = o.order_id
GROUP BY
  o.order_id,
  o.order_status,
  o.order_total,
  o.shipping_cost,
  o.created_at,
  o.social_source_id,
  c.customer_id,
  TRIM(c.first_name || ' ' || c.last_name),
  c.customer_tier,
  c.city,
  c.state_province,
  fc.center_id,
  fc.center_name;

CREATE OR REPLACE VIEW media_audience_signals_v AS
SELECT
  sp.post_id AS audience_signal_id,
  sp.platform,
  sp.posted_at,
  sp.post_text AS audience_signal_text,
  sp.sentiment_score,
  sp.virality_score,
  sp.momentum_flag,
  sp.likes_count,
  sp.shares_count,
  sp.views_count,
  i.influencer_id AS creator_id,
  i.handle AS creator_handle,
  i.display_name AS creator_name,
  i.niche AS creator_niche,
  (
    SELECT COUNT(*)
    FROM post_product_mentions ppm
    WHERE ppm.post_id = sp.post_id
  ) AS matched_content_assets
FROM social_posts sp
LEFT JOIN influencers i ON i.influencer_id = sp.influencer_id;

CREATE OR REPLACE VIEW media_distribution_capacity_v AS
SELECT
  fc.center_id AS distribution_hub_id,
  fc.center_name AS distribution_hub,
  fc.center_type AS hub_type,
  fc.city,
  fc.state_province,
  fc.capacity_units,
  fc.current_load_pct,
  p.product_id AS content_asset_id,
  p.product_name AS content_asset,
  p.category AS content_category,
  i.quantity_on_hand AS capacity_units_available,
  i.quantity_reserved AS capacity_units_reserved,
  i.quantity_incoming AS capacity_units_incoming,
  i.reorder_point AS capacity_intervention_threshold,
  df.predicted_demand,
  df.forecast_date,
  df.social_factor AS audience_signal_factor
FROM fulfillment_centers fc
JOIN inventory i ON i.center_id = fc.center_id
JOIN products p ON p.product_id = i.product_id
LEFT JOIN (
  SELECT product_id, region, forecast_date, predicted_demand, social_factor
  FROM (
    SELECT
      df.*,
      ROW_NUMBER() OVER (
        PARTITION BY df.product_id, df.region
        ORDER BY df.forecast_date DESC
      ) AS rn
    FROM demand_forecasts df
  )
  WHERE rn = 1
) df ON df.product_id = p.product_id
   AND (df.region = fc.state_province OR df.region IS NULL);

CREATE OR REPLACE VIEW media_creator_relationships_v AS
SELECT
  i.influencer_id AS creator_id,
  i.handle AS creator_handle,
  i.display_name AS creator_name,
  i.platform,
  i.niche,
  i.follower_count,
  i.engagement_rate,
  i.influence_score,
  b.brand_id AS studio_label_id,
  b.brand_name AS studio_or_label,
  bil.relationship_type,
  bil.post_count,
  bil.avg_engagement,
  bil.revenue_attributed AS content_revenue_attributed,
  NVL(edge.edge_count, 0) AS creator_edge_count,
  edge.avg_relationship_strength
FROM influencers i
LEFT JOIN brand_influencer_links bil ON bil.influencer_id = i.influencer_id
LEFT JOIN brands b ON b.brand_id = bil.brand_id
LEFT JOIN (
  SELECT
    from_influencer AS influencer_id,
    COUNT(*) AS edge_count,
    ROUND(AVG(strength), 3) AS avg_relationship_strength
  FROM influencer_connections
  GROUP BY from_influencer
) edge ON edge.influencer_id = i.influencer_id;

COMMENT ON TABLE media_content_assets_v IS
  'Media semantic view over products, brands, inventory, and audience signals. Use this for content assets, studios, labels, content categories, and capacity questions.';

COMMENT ON TABLE media_campaign_orders_v IS
  'Media semantic view over orders, customers, order_items, and fulfillment_centers. Use this for campaign orders, audience accounts, campaign value, and distribution hub questions.';

COMMENT ON TABLE media_audience_signals_v IS
  'Media semantic view over social_posts and creators. Use this for audience signals, urgency, virality, momentum, creator handles, and platform questions.';

COMMENT ON TABLE media_distribution_capacity_v IS
  'Media semantic view over fulfillment_centers, inventory, products, and demand_forecasts. Use this for rights capacity, distribution hubs, regional demand, and capacity risk.';

COMMENT ON TABLE media_creator_relationships_v IS
  'Media semantic view over influencers, creator graph edges, and studio or label relationships. Use this for creator influence, propagation, partnerships, and attributed revenue.';


PROMPT Building deterministic OML views and models
CREATE OR REPLACE VIEW oml_demand_training_v AS
WITH product_features AS (
    SELECT p.product_id, p.category, p.unit_price, NVL(eng.total_posts, 0) AS total_posts, NVL(eng.avg_sentiment, 0.5) AS avg_sentiment,
           NVL(eng.total_likes, 0) AS total_likes, NVL(eng.total_shares, 0) AS total_shares, NVL(eng.total_views, 0) AS total_views,
           NVL(eng.avg_virality, 0) AS avg_virality, NVL(eng.viral_posts, 0) AS viral_posts, NVL(eng.rising_posts, 0) AS rising_posts,
           NVL(sales.units_sold, 0) AS units_sold, NVL(sales.revenue, 0) AS revenue
    FROM products p
    LEFT JOIN (
        SELECT ppm.product_id, COUNT(*) AS total_posts, AVG(sp.sentiment_score) AS avg_sentiment, SUM(sp.likes_count) AS total_likes, SUM(sp.shares_count) AS total_shares,
               SUM(sp.views_count) AS total_views, AVG(sp.virality_score) AS avg_virality,
               SUM(CASE WHEN sp.momentum_flag IN ('viral', 'mega_viral') THEN 1 ELSE 0 END) AS viral_posts,
               SUM(CASE WHEN sp.momentum_flag = 'rising' THEN 1 ELSE 0 END) AS rising_posts
        FROM post_product_mentions ppm JOIN social_posts sp ON sp.post_id = ppm.post_id GROUP BY ppm.product_id
    ) eng ON eng.product_id = p.product_id
    LEFT JOIN (
        SELECT oi.product_id, SUM(oi.quantity) AS units_sold, SUM(oi.line_total) AS revenue
        FROM order_items oi JOIN orders o ON o.order_id = oi.order_id WHERE o.order_status NOT IN ('cancelled', 'returned') GROUP BY oi.product_id
    ) sales ON sales.product_id = p.product_id
    WHERE p.is_active = 1
), scored AS (
    SELECT pf.*, (NVL(pf.avg_virality, 0) * 0.45 + LEAST(NVL(pf.total_posts, 0), 40) * 0.9 + LEAST(NVL(pf.viral_posts, 0), 10) * 6 + LEAST(NVL(pf.rising_posts, 0), 15) * 2 + LEAST(NVL(pf.total_views, 0) / 2000, 25) + LEAST(NVL(pf.units_sold, 0), 80) * 0.2) AS demand_signal_score
    FROM product_features pf
), ranked AS (
    SELECT scored.*, NTILE(4) OVER (ORDER BY demand_signal_score DESC, avg_virality DESC, total_posts DESC, product_id) AS demand_quartile FROM scored
)
SELECT product_id, category, unit_price, total_posts, avg_sentiment, total_likes, total_shares, total_views, avg_virality, viral_posts, rising_posts, units_sold, revenue,
       CASE WHEN demand_quartile = 1 THEN 'SURGE' ELSE 'STABLE' END AS surge_label
FROM ranked;

CREATE OR REPLACE VIEW oml_customer_segment_v AS
WITH anchor AS (SELECT CAST(MAX(created_at) AS DATE) AS anchor_date FROM orders)
SELECT c.customer_id, NVL(c.lifetime_value, 0) AS lifetime_value, NVL(rfm.recency_days, 999) AS recency_days, NVL(rfm.frequency, 0) AS frequency,
       NVL(rfm.monetary, 0) AS monetary, NVL(rfm.avg_order_value, 0) AS avg_order_value, NVL(rfm.total_items, 0) AS total_items
FROM customers c
LEFT JOIN (
    SELECT o.customer_id, ROUND(MAX(a.anchor_date) - CAST(MAX(o.created_at) AS DATE)) AS recency_days, COUNT(DISTINCT o.order_id) AS frequency,
           SUM(o.order_total) AS monetary, AVG(o.order_total) AS avg_order_value, NVL(SUM(oi_cnt.item_count), 0) AS total_items
    FROM orders o CROSS JOIN anchor a LEFT JOIN (SELECT order_id, SUM(quantity) AS item_count FROM order_items GROUP BY order_id) oi_cnt ON oi_cnt.order_id = o.order_id
    WHERE o.order_status NOT IN ('cancelled', 'returned') GROUP BY o.customer_id
) rfm ON rfm.customer_id = c.customer_id
WHERE NVL(rfm.frequency, 0) > 0;

CREATE OR REPLACE VIEW oml_revenue_training_v AS
WITH anchor AS (SELECT CAST(MAX(created_at) AS DATE) AS anchor_date FROM orders)
SELECT o.order_id, c.customer_tier, o.order_status, NVL(c.lifetime_value, 0) AS lifetime_value, NVL(o.shipping_cost, 0) AS shipping_cost,
       NVL(o.demand_score, 0) AS demand_score, NVL(o.fulfillment_center_id, 0) AS fulfillment_center_id,
       ROUND(a.anchor_date - CAST(o.created_at AS DATE)) AS order_age_days, NVL(items.item_count, 0) AS item_count,
       NVL(items.distinct_products, 0) AS distinct_products, NVL(items.avg_item_price, 0) AS avg_item_price, NVL(items.max_item_price, 0) AS max_item_price,
       NVL(o.order_total, 0) AS target_revenue
FROM orders o CROSS JOIN anchor a JOIN customers c ON c.customer_id = o.customer_id
LEFT JOIN (SELECT order_id, SUM(quantity) AS item_count, COUNT(DISTINCT product_id) AS distinct_products, AVG(unit_price) AS avg_item_price, MAX(unit_price) AS max_item_price FROM order_items GROUP BY order_id) items ON items.order_id = o.order_id
WHERE o.order_status NOT IN ('cancelled', 'returned') AND NVL(o.order_total, 0) > 0;

CREATE OR REPLACE VIEW oml_product_cluster_v AS
SELECT p.product_id, NVL(p.unit_price, 0) AS unit_price, NVL(p.weight_kg, 0) AS weight_kg, NVL(sales.units_sold, 0) AS units_sold,
       NVL(sales.revenue, 0) AS revenue, NVL(sales.order_count, 0) AS order_count, NVL(eng.total_engagement, 0) AS total_engagement,
       NVL(eng.avg_sentiment, 0.5) AS avg_sentiment, NVL(eng.avg_virality, 0) AS avg_virality
FROM products p
LEFT JOIN (SELECT oi.product_id, SUM(oi.quantity) AS units_sold, SUM(oi.line_total) AS revenue, COUNT(DISTINCT oi.order_id) AS order_count FROM order_items oi JOIN orders o ON o.order_id = oi.order_id WHERE o.order_status NOT IN ('cancelled', 'returned') GROUP BY oi.product_id) sales ON sales.product_id = p.product_id
LEFT JOIN (SELECT ppm.product_id, SUM(sp.likes_count + sp.shares_count + sp.views_count) AS total_engagement, AVG(sp.sentiment_score) AS avg_sentiment, AVG(sp.virality_score) AS avg_virality FROM post_product_mentions ppm JOIN social_posts sp ON sp.post_id = ppm.post_id GROUP BY ppm.product_id) eng ON eng.product_id = p.product_id
WHERE p.is_active = 1;

CREATE TABLE oml_demand_settings (setting_name VARCHAR2(30), setting_value VARCHAR2(4000));
CREATE TABLE oml_customer_segment_settings (setting_name VARCHAR2(30), setting_value VARCHAR2(4000));
CREATE TABLE oml_revenue_settings (setting_name VARCHAR2(30), setting_value VARCHAR2(4000));
CREATE TABLE oml_product_cluster_settings (setting_name VARCHAR2(30), setting_value VARCHAR2(4000));

COMMIT;

CREATE OR REPLACE PROCEDURE rebuild_media_oml_models
AS
BEGIN
    DBMS_DATA_MINING.CREATE_MODEL(model_name => 'DEMAND_SURGE_MODEL', mining_function => DBMS_DATA_MINING.CLASSIFICATION, data_table_name => 'OML_DEMAND_TRAINING_V', case_id_column_name => 'PRODUCT_ID', target_column_name => 'SURGE_LABEL', settings_table_name => 'OML_DEMAND_SETTINGS');
    DBMS_DATA_MINING.CREATE_MODEL(model_name => 'CUSTOMER_SEGMENT_MODEL', mining_function => DBMS_DATA_MINING.CLUSTERING, data_table_name => 'OML_CUSTOMER_SEGMENT_V', case_id_column_name => 'CUSTOMER_ID', settings_table_name => 'OML_CUSTOMER_SEGMENT_SETTINGS');
    DBMS_DATA_MINING.CREATE_MODEL(model_name => 'REVENUE_PREDICT_MODEL', mining_function => DBMS_DATA_MINING.REGRESSION, data_table_name => 'OML_REVENUE_TRAINING_V', case_id_column_name => 'ORDER_ID', target_column_name => 'TARGET_REVENUE', settings_table_name => 'OML_REVENUE_SETTINGS');
    DBMS_DATA_MINING.CREATE_MODEL(model_name => 'PRODUCT_CLUSTER_MODEL', mining_function => DBMS_DATA_MINING.CLUSTERING, data_table_name => 'OML_PRODUCT_CLUSTER_V', case_id_column_name => 'PRODUCT_ID', settings_table_name => 'OML_PRODUCT_CLUSTER_SETTINGS');
END;
/
BEGIN rebuild_media_oml_models; END;
/


PROMPT =====================================================
PROMPT Media loader validation summary
PROMPT =====================================================
COLUMN validation_area FORMAT A32
COLUMN validation_name FORMAT A42
COLUMN validation_value FORMAT A24
SELECT 'schema' AS validation_area, 'current_user' AS validation_name, USER AS validation_value FROM dual
UNION ALL SELECT 'quality', 'invalid_media_objects', TO_CHAR(COUNT(*)) FROM user_objects
WHERE status <> 'VALID'
  AND (object_name LIKE 'MEDIA_%'
       OR object_name IN ('ORDERS_DV','PRODUCTS_INVENTORY_DV','REFRESH_MEDIA_VECTOR_ARTIFACTS','REBUILD_MEDIA_OML_MODELS','SEARCH_PRODUCTS_BY_TEXT','INFLUENCER_NETWORK'))
UNION ALL SELECT 'core_rows', 'brands', TO_CHAR(COUNT(*)) FROM brands
UNION ALL SELECT 'core_rows', 'products', TO_CHAR(COUNT(*)) FROM products
UNION ALL SELECT 'core_rows', 'customers', TO_CHAR(COUNT(*)) FROM customers
UNION ALL SELECT 'core_rows', 'orders', TO_CHAR(COUNT(*)) FROM orders
UNION ALL SELECT 'core_rows', 'order_items', TO_CHAR(COUNT(*)) FROM order_items
UNION ALL SELECT 'signals', 'social_posts', TO_CHAR(COUNT(*)) FROM social_posts
UNION ALL SELECT 'signals', 'post_product_mentions', TO_CHAR(COUNT(*)) FROM post_product_mentions
UNION ALL SELECT 'graph', 'influencer_connections', TO_CHAR(COUNT(*)) FROM influencer_connections
UNION ALL SELECT 'graph', 'brand_influencer_links', TO_CHAR(COUNT(*)) FROM brand_influencer_links
UNION ALL SELECT 'spatial', 'fulfillment_zones', TO_CHAR(COUNT(*)) FROM fulfillment_zones
UNION ALL SELECT 'spatial', 'demand_regions', TO_CHAR(COUNT(*)) FROM demand_regions
UNION ALL SELECT 'vector', 'product_embeddings', TO_CHAR(COUNT(*)) FROM product_embeddings
UNION ALL SELECT 'vector', 'post_embeddings', TO_CHAR(COUNT(*)) FROM post_embeddings
UNION ALL SELECT 'vector', 'semantic_matches', TO_CHAR(COUNT(*)) FROM semantic_matches
UNION ALL SELECT 'oml', 'mining_models', TO_CHAR(COUNT(*)) FROM user_mining_models WHERE model_name IN ('DEMAND_SURGE_MODEL','CUSTOMER_SEGMENT_MODEL','REVENUE_PREDICT_MODEL','PRODUCT_CLUSTER_MODEL')
UNION ALL SELECT 'duality', 'json_duality_views', TO_CHAR(COUNT(*)) FROM user_json_duality_views WHERE view_name IN ('ORDERS_DV','PRODUCTS_INVENTORY_DV')
UNION ALL SELECT 'semantic_views', 'media_views', TO_CHAR(COUNT(*)) FROM user_views WHERE view_name IN ('MEDIA_CONTENT_ASSETS_V','MEDIA_CAMPAIGN_ORDERS_V','MEDIA_AUDIENCE_SIGNALS_V','MEDIA_DISTRIBUTION_CAPACITY_V','MEDIA_CREATOR_RELATIONSHIPS_V')
ORDER BY validation_area, validation_name;

PROMPT Media platform handoff loader complete.
